        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial state
    ret = gpiod_line_set_value(line_2, state);
    if (ret) {
        fprintf(stderr, "Failed to set line 2: %d\n", ret);
        gpiod_line_release(line_3);
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_set_value(line_3, state);
    if (ret) {
        fprintf(stderr, "Failed to set line 3: %d\n", ret);
        gpiod_line_release(line_3);
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

