        state = data.value;

        ret = gpiod_line_get_value(line_3, &data);
        if (ret) {
            fprintf(stderr, "Failed to get line 3: %d\n");
            break;
        }
        state = (state << 1) | data.value;

        // Print state
        printf("State: %d\n", state);

        // Toggle state
        state = 1 - state;

        // Set new state
        ret = gpiod_line_set_value(line_2, state & 1);
        if (ret) {
            fprintf(stderr, "Failed to set line 2: %d\n", ret);
            break;
