#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN 2

int main() {
    int ret;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    struct gpiod_line_event_data data;
    struct gpiod_line_event_data_validity validity;

    // Open the GPIO chip
    line = gpiod_chip_get_line(GPIO_CHIP_NAME, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to open GPIO chip '%s'\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Export the GPIO pin
    ret = gpiod_line_export(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO pin %d: %s\n", GPIO_PIN, gpiod_error_str(ret));
        gpiod_line_release(line);
        return 1;
    }

    // Set the direction of the GPIO pin to output
    ret = gpiod_line_request_output(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as output: %s\n", GPIO_PIN, gpiod_error_str(ret));
        gpiod_line_release(line);
        return 1;
    }

    // Set the initial state of the GPIO pin to 0
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d to 0: %s\n", GPIO_PIN, gpiod_error_str(ret));
        gpiod_line_release(line);
        return 1;
    }

    // Print the initial state of the GPIO pin
    printf("Initial state: 0\n");

    // Loop indefinitely
    while (1) {
        // Read the current state of the GPIO pin
        ret = gpiod_line_get_value(line, &data);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO pin %d: %s\n", GPIO_PIN, gpiod_error_str(ret));
            break;
        }

        // Check the validity of the reading
        if (gpiod_line_event_data_validity(&data, &validity) < 0) {
            fprintf(stderr, "Failed to check validity of GPIO pin %d reading\n", GPIO_PIN);
            break;
        }

        if (!validity.valid) {
            fprintf(stderr, "Invalid reading from GPIO pin %d\n", GPIO_PIN);
            break;
        }

        // Print the current state of the GPIO pin
        printf("State: %d\n", data.value);

        // Toggle the state of the GPIO pin
        ret = gpiod_line_set_value(line, !data.value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO pin %d to %d: %s\n", GPIO_PIN, !data.value, gpiod_error_str(ret));
            break;
        }

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Release the GPIO pin
    gpiod_line_release(line);

    return 0;
}

