#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0

int main() {
    int i2c_fd;
    int ret;
    uint16_t reading;

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C bus to the ADC address
    ret = ioctl(i2c_fd, I2C_SLAVE, ADC_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the ADC
    uint8_t config = 0b11000000; // Single-ended, 16-bit, 250 SPS
    ret = i2c_smbus_write_byte_data(i2c_fd, 0x01, config);
    if (ret < 0) {
        perror("Failed to configure ADC");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO for interrupt handling
    int gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        perror("Failed to initialize GPIO");
        close(i2c_fd);
        return 1;
    }

    // Set up interrupt handling
    int gpio = gpioServo(gpio_fd, 17); // Use GPIO 17 for interrupt
    if (gpio < 0) {
        perror("Failed to set up GPIO interrupt");
        gpioTerminate(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Set up interrupt handler
    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDnControl(gpio, PI_PUD_UP);
    gpioSetAlertFunc(gpio, gpioRead);

    // Main loop
    while (1) {
        // Read the ADC value
        ret = i2c_smbus_read_word_data(i2c_fd, 0x00);
        if (ret < 0) {
            perror("Failed to read ADC value");
            gpioTerminate(gpio_fd);
            close(i2c_fd);
            return 1;
        }
        reading = ret;

        // Print the reading
        printf("%d\n", reading);

        // Wait for 0.5 seconds
        usleep(500000);

        // Check for interrupt
        if (gpioRead(gpio) == 1) {
            // Interrupt detected, exit cleanly
            gpioTerminate(gpio_fd);
            close(i2c_fd);
            return 0;
        }
    }

    // Clean up on exit
    gpioTerminate(gpio_fd);
    close(i2c_fd);
    return 0;
}

