#include <errno.h>

#define MLX90614_ADDRESS 0x5A
#define MLX90614_REG_AMBIENT_TEMPERATURE 0x00
#define MLX90614_REG_OBJECT_TEMPERATURE 0x01

int main() {
    int i2c_fd = -1;
    int ret;

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    // Set the I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        goto cleanup;
    }

    while (1) {
        // Read the ambient temperature
        uint16_t ambient_temp;
        ret = i2c_smbus_read_byte_data(i2c_fd, MLX90614_REG_AMBIENT_TEMPERATURE);
        if (ret < 0) {
            perror("Failed to read ambient temperature");
            goto cleanup;
        }
        ambient_temp = (ret << 8) | i2c_smbus_read_byte_data(i2c_fd, MLX90614_REG_AMBIENT_TEMPERATURE);
        printf("Ambient temperature: %d°C\n", (ambient_temp * 175.0) / 65536 - 256);

        // Read the object temperature
        uint16_t object_temp;
        ret = i2c_smbus_read_byte_data(i2c_fd, MLX90614_REG_OBJECT_TEMPERATURE);
        if (ret < 0) {
            perror("Failed to read object temperature");
            goto cleanup;
        }
        object_temp = (ret << 8) | i2c_smbus_read_byte_data(i2c_fd, MLX90614_REG_OBJECT_TEMPERATURE);
        printf("Object temperature: %d°C\n", (object_temp * 175.0) / 65536 - 256);

        // Wait 5 seconds
        usleep(5000000);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return errno != 0 ? errno : 0;
}

