        ret = gpiod_line_set_value(trigger_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set trigger line high: %s\n", gpiod_error_str(ret));
            gpiod_line_event_unsubscribe(echo_line);
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_cleanup();
            return 1;
        }

        // Wait for the echo
        usleep(100000);  // 100ms delay

        ret = gpiod_line_set_value(trigger_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set trigger line low: %s\n", gpiod_error_str(ret));
            gpiod_line_event_unsubscribe(echo_line);
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_cleanup();
            return 1;
        }

        // Wait for the echo to arrive
        ret = gpiod_line_event_wait(echo_line, &event, 1000000);  // 1s timeout
        if (ret < 0) {
