            gpiod_line_event_unsubscribe(echo_line);
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_cleanup();
            return 1;
        }

        // Print the distance
        printf("Distance: %d cm\n", event.timestamp / 58);  // 58 us per cm

        // Sleep for 60 seconds
        sleep(DELAY);
    }

    // Clean up
    gpiod_line_event_unsubscribe(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_cleanup();

