    int config = ADS1115_REG_CONFIG_PGA_4_096V | ADS1115_REG_CONFIG_MODE_CONTINUOUS | ADS1115_REG_CONFIG_DR_1600SPS;
    uint16_t reading = 0;

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Write the configuration to the ADS1115
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Failed to write configuration");
        close(i2c_fd);
        return 1;
    }

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        close(i2c_fd);
        return 1;
    }

    // Set up a signal handler to clean up on exit
    signal(SIGINT, cleanup);

    while (1) {
        // Read the data from the ADS1115
        if (read(i2c_fd, &reading, 2) != 2) {
            perror("Failed to read data");
            cleanup();
            return 1;
        }

        // Check the validity of the reading
        if (reading & 0x8000) {
            printf("Invalid reading: 0x%04x\n", reading);
            continue;
        }

        // Print the reading
        printf("Reading: %d\n", reading);

        // Wait for 5 seconds
        sleep(5);
    }

    cleanup();
    return 0;
}

void cleanup() {
    // Release the GPIO library
    gpioTerminate();

    // Close the I2C bus
    close(i2c_fd);
}

