#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_ADDRESS 0x40
#define I2C_BUS "/dev/i2c-1"

int i2c_open() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
    return fd;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }
    if (write(fd, &value, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t* value) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(1);
    }
    return 0;
}

int main() {
    int fd = i2c_open();
    uint8_t config = 0x00; // Reset configuration register
    i2c_write(fd, 0xE5, config);

    while (1) {
        uint8_t data[2];
        i2c_write(fd, 0xE0, 0x00); // Read temperature
        if (i2c_read(fd, 0xE0, data) != 0) {
            continue;
        }
        uint16_t temperature = (data[0] << 8) | data[1];
        if (temperature & 0x8000) {
            temperature = -temperature;
        }
        printf("Temperature: %.2f°C\n", (float)temperature / 128.0);

        i2c_write(fd, 0xE3, 0x00); // Read humidity
        if (i2c_read(fd, 0xE3, data) != 0) {
            continue;
        }
        uint16_t humidity = (data[0] << 8) | data[1];
        if (humidity & 0x8000) {
            humidity = -humidity;
        }
        printf("Humidity: %.2f%%\n", (float)humidity / 128.0);

        sleep(5);
    }

    close(fd);
    return 0;
}

