    struct gpiod_line_event_data data;

    // Open the GPIO chip
    line = gpiod_chip_get_line(GPIO_CHIP_NAME, GPIO_LINE_NUMBER);
    if (!line) {
        fprintf(stderr, "Failed to get line %d on chip %s: %s\n", GPIO_LINE_NUMBER, GPIO_CHIP_NAME, gpiod_error());
        return 1;
    }

    // Export the line
    ret = gpiod_line_request_output(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_NUMBER, gpiod_error());
        gpiod_line_release(line);
        return 1;
    }

    // Set the initial state to 0
    ret = gpiod_line_set_value(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to set line %d to 0: %s\n", GPIO_LINE_NUMBER, gpiod_error());
        gpiod_line_release(line);
        return 1;
    }

    // Set up a line event handler
    ret = gpiod_line_event_subscribe(line, GPIOD_LINE_EVENT_VALUE_CHANGED, &event, &data, NULL);
    if (ret) {
        fprintf(stderr, "Failed to subscribe to line %d events: %s\n", GPIO_LINE_NUMBER, gpiod_error());
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle the line state
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret) {
            fprintf(stderr, "Failed to set line %d: %s\n", GPIO_LINE_NUMBER, gpiod_error());
            break;
        }

        // Print the current state
        printf("%d\n", gpiod_line_get_value(line));

        // Sleep for 1 second
        usleep(1000000);
    }

    // Unsubscribe from events
    gpiod_line_event_unsubscribe(&event);

    // Release the line
    gpiod_line_release(line);

    return 0;
}

