#define GPIO17 17
#define GPIO18 18
#define TRIGGER_PIN GPIO17
#define ECHO_PIN  GPIO18
#define MAX_RETRIES 5

int main() {
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret;

    // Initialize GPIO lines
    ret = gpiod_chip_open("/dev/gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(ret));
        return 1;
    }

    ret = gpiod_chip_request_lines(gpiod_chip_get_id(ret), &trigger_line, &echo_line, TRIGGER_PIN, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_REQUEST_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", gpiod_error_str(ret));
        gpiod_chip_close(gpiod_chip_get_id(ret));
        return 1;
    }

    // Set up echo line as input
    ret = gpiod_line_request(echo_line, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_REQUEST_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", gpiod_error_str(ret));
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(gpiod_chip_get_id(ret));
        return 1;
    }

    // Set up trigger line as output
    ret = gpiod_line_direction(trigger_line, GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set direction of trigger line: %s\n", gpiod_error_str(ret));
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(gpiod_chip_get_id(ret));
        return 1;
    }

    while (1) {
        // Trigger a pulse on the trigger line
        ret = gpiod_line_set_value(trigger_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set trigger line: %s\n", gpiod_error_str(ret));
            break;
        }
        usleep(10 * 1000); // 10ms pulse

        ret = gpiod_line_set_value(trigger_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to clear trigger line: %s\n", gpiod_error_str(ret));
            break;
        }

        int retries = 0;
        int value;
        while (retries < MAX_RETRIES) {
            ret = gpiod_line_get_value(echo_line, &value);
            if (ret < 0) {
                fprintf(stderr, "Failed to get echo line value: %s\n", gpiod_error_str(ret));
                break;
            }
            if (value == 1) {
                break;
            }
            retries++;
            usleep(1000); // 1ms delay
        }

        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "No response from echo line\n");
            break;
        }

        // Calculate distance
        int distance = (retries * 1000) / 2; // 1ms delay, 29.1us per us, 29.1cm per us
        printf("Distance: %d cm\n", distance);

        sleep(1);
    }

    // Release resources
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(gpiod_chip_get_id(ret));

    return 0;
}

