#define SERIAL_DEVICE "/dev/ttyUSB0" // Replace with your serial device path

int main() {
    int fd = -1;
    struct termios oldtio, newtio;

    // Open the serial device
    fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Failed to open serial device");
        goto cleanup;
    }

    // Save the current serial settings
    if (tcgetattr(fd, &oldtio) != 0) {
        perror("Failed to get serial settings");
        goto cleanup;
    }

    // Set the new serial settings
    newtio.c_cflag = B9600 | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNBRK | IGNPAR | ICRNL | INLCR;
    newtio.c_oflag = 0;
    newtio.c_lflag = 0;
    newtio.c_cc[VMIN] = 1;
    newtio.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &newtio) != 0) {
        perror("Failed to set serial settings");
        goto cleanup;
    }

    // Read from the serial device
    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, 256);
    if (bytes_read < 0) {
        perror("Failed to read from serial device");
        goto cleanup;
    }

    // Print the received data
    printf("Received: %s\n", buffer);

cleanup:
    // Restore the original serial settings
    if (fd >= 0) {
        if (tcsetattr(fd, TCSANOW, &oldtio) != 0) {
            perror("Failed to restore serial settings");
        }
        close(fd);
    }

    return (fd < 0) ? 1 : 0;
}

