        return 1;
    }

    // Export the line
    ret = gpiod_line_request_output(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_NUMBER, gpiod_error());
        gpiod_line_release(line);
        return 1;
    }

    // Set the initial state to 0
    ret = gpiod_line_set_value(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to set line %d to 0: %s\n", GPIO_LINE_NUMBER, gpiod_error());
        gpiod_line_release(line);
        return 1;
    }

    // Print the initial state
    printf("Initial state: 0\n");

    // Main loop
    while (1) {
        // Toggle the state
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret) {
            fprintf(stderr, "Failed to set line %d: %s\n", GPIO_LINE_NUMBER, gpiod_error());
            break;
        }

        // Print the new state
        printf("State: %d\n", gpiod_line_get_value(line));

        // Wait for 0.5 seconds
        usleep(500000);
    }

    // Release the line
    gpiod_line_release(line);

    return 0;
}

