#include <errno.h>

#define I2C_SLAVE 0x0703
#define I2C_SLAVE_ADDR 0x44
#define OPT3001_REG_CONFIG 0x00
#define OPT3001_REG_DATA 0x01

int main() {
    int i2c_fd = -1;
    int ret;

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Write the configuration register
    uint8_t config = 0x00; // Default configuration
    ret = write(i2c_fd, &config, 1);
    if (ret != 1) {
        perror("Failed to write configuration register");
        close(i2c_fd);
        return 1;
    }

    // Read the data register
    uint16_t data;
    ret = read(i2c_fd, &data, 2);
    if (ret != 2) {
        perror("Failed to read data register");
        close(i2c_fd);
        return 1;
    }

    // Print the reading
    printf("OPT3001 reading: %d\n", data);

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

