#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/select.h>

#define SERIAL_DEVICE "/dev/ttyUSB0" // Replace with your serial device path

int main() {
    int fd = -1;
    struct termios oldtio, newtio;
    char buffer[256];

    // Open the serial device
    fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Failed to open serial device");
        return 1;
    }

    // Save the current termios settings
    if (tcgetattr(fd, &oldtio) < 0) {
        perror("Failed to get current termios settings");
        close(fd);
        return 1;
    }

    // Set the new termios settings
    newtio = oldtio;
    newtio.c_cflag = B9600 | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNBRK | IGNPAR;
    newtio.c_oflag = 0;
    newtio.c_lflag = 0;
    if (tcsetattr(fd, TCSANOW, &newtio) < 0) {
        perror("Failed to set new termios settings");
        close(fd);
        return 1;
    }

    // Set up a timeout for reading
    struct timeval tv;
    tv.tv_sec = 0;
    tv.tv_usec = 100000; // 100ms
    if (select(fd + 1, NULL, NULL, NULL, &tv) < 0) {
        perror("Failed to set select timeout");
        close(fd);
        return 1;
    }

    // Read from the serial device
    while (1) {
        ssize_t bytes_read = read(fd, buffer, 256);
        if (bytes_read < 0) {
            perror("Failed to read from serial device");
            break;
        }
        if (bytes_read == 0) {
            // No data available, exit
            break;
        }
        buffer[bytes_read] = '\0';
        printf("%s\n", buffer);
    }

    // Restore the original termios settings
    if (tcsetattr(fd, TCSANOW, &oldtio) < 0) {
        perror("Failed to restore original termios settings");
    }

    // Close the serial device
    close(fd);

    return 0;
}

