#define DELAY 60

int main() {
    int ret;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int value;

    // Open the GPIO chip
    line = gpiod_chip_get_line(GPIO_CHIP_NAME, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        return EXIT_FAILURE;
    }

    // Export the GPIO pin
    ret = gpiod_line_export(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to export line: %s\n", gpiod_error_str(ret));
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Set the direction of the GPIO pin to output
    ret = gpiod_line_request_output(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output: %s\n", gpiod_error_str(ret));
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Main loop
    for (int i = 0; i < CYCLES; i++) {
        // Set the GPIO pin to high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value: %s\n", gpiod_error_str(ret));
            gpiod_line_release(line);
            return EXIT_FAILURE;
        }

        // Wait for 60 seconds
        sleep(DELAY);

        // Read the value of the GPIO pin
        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to get value: %s\n", gpiod_error_str(ret));
            gpiod_line_release(line);
            return EXIT_FAILURE;
        }

        // Check if the value is valid
        if (value < 0 || value > 1) {
            fprintf(stderr, "Invalid value: %d\n", value);
            gpiod_line_release(line);
            return EXIT_FAILURE;
        }

        // Set the GPIO pin to low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value: %s\n", gpiod_error_str(ret));
            gpiod_line_release(line);
            return EXIT_FAILURE;
        }

        // Wait for 60 seconds
        sleep(DELAY);
    }

    // Release the GPIO pin
    gpiod_line_release(line);

    return EXIT_SUCCESS;
}

