#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2
#define DURATION 100000 // 0.1 seconds in microseconds

int main() {
    int ret;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    struct gpiod_line_event *events;
    size_t num_events;

    // Open the GPIO chip
    line = gpiod_chip_get_line(GPIO_CHIP, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        return EXIT_FAILURE;
    }

    // Export the line
    ret = gpiod_line_export(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to export line: %d\n", ret);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Set the direction of the line to output
    ret = gpiod_line_request_output(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to request output: %d\n", ret);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Set the initial state of the line to 1 (high)
    ret = gpiod_line_set_value(line, 1);
    if (ret) {
        fprintf(stderr, "Failed to set initial value: %d\n", ret);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Register for events
    ret = gpiod_line_event_subscribe(line, GPIOD_LINE_EVENT_VALUE, &events, &num_events);
    if (ret) {
        fprintf(stderr, "Failed to subscribe to events: %d\n", ret);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        // Print the current state of the line
        ret = gpiod_line_get_value(line, &event);
        if (ret) {
            fprintf(stderr, "Failed to get value: %d\n", ret);
            gpiod_line_event_unsubscribe(&events, num_events);
            gpiod_line_release(line);
            return EXIT_FAILURE;
        }
        printf("State: %d\n", event.value);

        // Toggle the state of the line
        ret = gpiod_line_set_value(line, !event.value);
        if (ret) {
            fprintf(stderr, "Failed to set value: %d\n", ret);
            gpiod_line_event_unsubscribe(&events, num_events);
            gpiod_line_release(line);
            return EXIT_FAILURE;
        }

        // Wait for 0.1 seconds
        usleep(DURATION);
    }

    // Unsubscribe from events
    gpiod_line_event_unsubscribe(&events, num_events);

    // Release the line
    gpiod_line_release(line);

    return EXIT_SUCCESS;
}

