#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define HTU21D_ADDRESS 0x40
#define HTU21D_READ_COMMAND 0xE5
#define HTU21D_WRITE_COMMAND 0xE6
#define HTU21D_READ_TIMEOUT 1000 // 1 second

int i2c_open(const char *filename) {
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    return fd;
}

int i2c_write(int fd, uint8_t address, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    if (write(fd, &value, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    return 0;
}

uint16_t i2c_read(int fd) {
    uint16_t value;
    if (read(fd, &value, 2) != 2) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
    return value;
}

bool is_valid_reading(uint16_t reading) {
    return (reading & 0x0001) == 0;
}

int main() {
    const char *filename = "/dev/i2c-1";
    int fd = i2c_open(filename);

    while (1) {
        i2c_write(fd, HTU21D_ADDRESS, HTU21D_READ_COMMAND);
        uint16_t reading = i2c_read(fd);
        if (!is_valid_reading(reading)) {
            fprintf(stderr, "Invalid reading: 0x%04x\n", reading);
            continue;
        }
        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", (reading >> 9) * 175.0 / 65536.0 - 45.0, (reading & 0x00FF) * 100.0 / 255.0);
        sleep(60);
    }

    close(fd);
    return 0;
}

