        duty_cycle = (duty_cycle + DUTY_CYCLE_INCREMENT) % (DUTY_CYCLE_MAX - DUTY_CYCLE_MIN + 1);
    }

    gpioServoDestroy(pwm);
    pigpioCleanup();
    return 0;
}

