#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ENABLE2 0x81
#define TCS34725_ID 0x44
#define TCS34725_R 0x0F
#define TCS34725_G 0x10
#define TCS34725_B 0x11
#define TCS34725_C 0x12
#define TCS34725_ENABLE_INT 0x00

int i2c_open(const char *filename) {
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }
    return fd;
}

int i2c_write(int fd, uint8_t address, uint8_t reg, uint8_t value) {
    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .buf = &value,
        .len = 1
    };
    struct i2c_msg msgs[] = {msg};
    int ret = ioctl(fd, I2C_SLAVE, address);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    ret = i2c_transfer(fd, msgs, 1);
    if (ret < 0) {
        perror("Failed to write to I2C device");
        exit(1);
    }
    return 0;
}

uint16_t i2c_read(int fd, uint8_t address, uint8_t reg) {
    uint16_t value;
    struct i2c_msg msg = {
        .addr = address,
        .flags = I2C_M_RD,
        .buf = &value,
        .len = 2
    };
    struct i2c_msg msgs[] = {msg};
    int ret = i2c_transfer(fd, msgs, 1);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        exit(1);
    }
    return value;
}

int main() {
    int fd = i2c_open("/dev/i2c-1");
    if (i2c_read(fd, TCS34725_ADDRESS, TCS34725_ID) != TCS34725_ID) {
        fprintf(stderr, "Device not found\n");
        close(fd);
        return 1;
    }
    i2c_write(fd, TCS34725_ADDRESS, TCS34725_ENABLE, TCS34725_ENABLE);
    while (1) {
        uint16_t r = i2c_read(fd, TCS34725_ADDRESS, TCS34725_R);
        uint16_t g = i2c_read(fd, TCS34725_ADDRESS, TCS34725_G);
        uint16_t b = i2c_read(fd, TCS34725_ADDRESS, TCS34725_B);
        uint16_t c = i2c_read(fd, TCS34725_ADDRESS, TCS34725_C);
        printf("R: %d, G: %d, B: %d, C: %d\n", r, g, b, c);
        usleep(200000);
    }
    close(fd);
    return 0;
}

