#define WIDTH 3280
#define HEIGHT 2464
#define FRAMES 1
#define FILENAME "image.jpg"

int main() {
    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_streamparm parm;
    struct v4l2_capability cap;
    struct v4l2_format fmt_out;
    char *dev_name = "/dev/video0";
    char *filename = FILENAME;
    int ret;

    // Open the device
    fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    // Get device capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to get device capabilities");
        close(fd);
        return 1;
    }

    // Check if device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return 1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    // Set streaming parameters
    memset(&parm, 0, sizeof(parm));
    parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    parm.streamparm.capture.timeperframe.numerator = 1;
    parm.streamparm.capture.timeperframe.denominator = 30;
    ret = ioctl(fd, VIDIOC_S_PARM, &parm);
    if (ret < 0) {
        perror("Failed to set streaming parameters");
        close(fd);
        return 1;
    }

    // Start streaming
    ret = ioctl(fd, VIDIOC_STREAMON, &fmt.type);
    if (ret < 0) {
        perror("Failed to start streaming");
        close(fd);
        return 1;
    }

    // Capture frame
    char *buf = malloc(WIDTH * HEIGHT * 3);
    if (!buf) {
        perror("Failed to allocate memory");
        close(fd);
        return 1;
    }
    ret = read(fd, buf, WIDTH * HEIGHT * 3);
    if (ret < 0) {
        perror("Failed to read frame");
        free(buf);
        close(fd);
        return 1;
    }

    // Save frame to file
    FILE *f = fopen(filename, "wb");
    if (!f) {
        perror("Failed to open file");
        free(buf);
        close(fd);
        return 1;
    }
    fwrite(buf, 1, ret, f);
    fclose(f);
    free(buf);

    // Stop streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, &fmt.type);
    if (ret < 0) {
        perror("Failed to stop streaming");
    }

    // Release resources
    close(fd);
    return 0;
}

