#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

// SSD1306 command bytes
#define SSD1306_DISPLAYOFF 0xAE
#define SSD1306_DISPLAYON 0xAF
#define SSD1306_SETCONTRAST 0xA8
#define SSD1306_SETDISPLAYOFFSET 0xD3
#define SSD1306_SETCOLUMNADDR 0x15
#define SSD1306_SETROWADDR 0x75
#define SSD1306_MEMORYMODE 0x20
#define SSD1306_CHARGEPUMP 0x24

// Function to send a byte over I2C
void i2c_write_byte(int fd, uint8_t byte) {
    uint8_t buffer[1];
    buffer[0] = byte;
    if (write(fd, buffer, 1) != 1) {
        perror("i2c_write_byte");
        exit(1);
    }
}

// Function to send a command to the SSD1306
void i2c_send_command(int fd, uint8_t command) {
    i2c_write_byte(fd, command);
}

// Function to send data to the SSD1306
void i2c_send_data(int fd, uint8_t data) {
    i2c_write_byte(fd, data);
}

// Function to initialize the SSD1306
void init_ssd1306(int fd) {
    // Reset the display
    i2c_send_command(fd, SSD1306_DISPLAYOFF);
    usleep(100000);

    // Set the display mode
    i2c_send_command(fd, SSD1306_SETDISPLAYOFFSET);
    i2c_send_data(fd, 0x0);
    i2c_send_command(fd, SSD1306_SETDISPLAYOFFSET);
    i2c_send_data(fd, 0x0);

    // Set the column and row addresses
    i2c_send_command(fd, SSD1306_SETCOLUMNADDR);
    i2c_send_data(fd, 0x00);
    i2c_send_data(fd, 0x00);
    i2c_send_command(fd, SSD1306_SETROWADDR);
    i2c_send_data(fd, 0x00);
    i2c_send_data(fd, SSD1306_HEIGHT - 1);

    // Set the memory mode
    i2c_send_command(fd, SSD1306_MEMORYMODE);
    i2c_send_data(fd, 0x00);

    // Set the charge pump
    i2c_send_command(fd, SSD1306_CHARGEPUMP);
    i2c_send_data(fd, 0x14);

    // Turn on the display
    i2c_send_command(fd, SSD1306_DISPLAYON);
}

int main() {
    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(1);
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }

    // Initialize the SSD1306
    init_ssd1306(i2c_fd);

    // Initialize the GPIO for the interrupt
    int gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    // Set up the interrupt handler
    gpioSetMode(gpio_fd, 17, PI_INPUT);
    gpioSetEdge(gpio_fd, 17, BOTH);
    gpioSetAlertFunc(gpio_fd, 17, NULL);

    // Main loop
    while (1) {
        // Read the GPIO value
        int gpio_value = gpioRead(gpio_fd, 17);
        if (gpio_value == 1) {
            // Exit on interrupt
            break;
        }

        // Clear the display
        for (int y = 0; y < SSD1306_HEIGHT; y++) {
            for (int x = 0; x < SSD1306_WIDTH; x++) {
                i2c_send_data(i2c_fd, 0);
            }
        }

        // Draw a line
        for (int x = 0; x < SSD1306_WIDTH; x++) {
            i2c_send_data(i2c_fd, x % 2);
        }

        // Draw a number
        char buffer[10];
        sprintf(buffer, "%d", x);
        for (int i = 0; i < strlen(buffer); i++) {
            i2c_send_data(i2c_fd, buffer[i]);
        }

        // Update the display
        i2c_send_command(i2c_fd, 0x15);
        i2c_send_data(i2c_fd, 0x00);
        i2c_send_data(i2c_fd, SSD1306_HEIGHT - 1);
        i2c_send_command(i2c_fd, 0x75);
        i2c_send_data(i2c_fd, 0x00);
        i2c_send_data(i2c_fd, SSD1306_WIDTH - 1);
        i2c_send_command(i2c_fd, 0x5C);
        i2c_send_data(i2c_fd, 0x00);

        // Wait 0.1 seconds
        usleep(100000);
    }

    // Clean up
    gpioTerminate(gpio_fd);
    close(i2c_fd);
    return 0;
}

