        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret) {
        fprintf(stderr, "Failed to set format: %d\n", ret);
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret) {
        fprintf(stderr, "Failed to request buffers: %d\n", ret);
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Map the buffer
    buf = mmap(NULL, req.count * fmt.fmt.pix.bytesperline * fmt.fmt.pix.height, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buf == MAP_FAILED) {
        fprintf(stderr, "Failed to map buffer: %s\n", strerror(errno));
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the buffer info
    memset(&buf_info, 0, sizeof(buf_info));
    buf_info.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_QBUF, &buf_info);
    if (ret) {
        fprintf(stderr, "Failed to get buffer info: %d\n", ret);
        munmap(buf, req.count * fmt.fmt.pix.bytesperline * fmt.fmt.pix.height);
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the buffer to the current buffer
    buf_info.index = 0;
    ret = ioctl(fd, VIDIOC_QBUF, &buf_info);
    if (ret) {
        fprintf(stderr, "Failed to set buffer: %d\n", ret);
        munmap(buf, req.count * fmt.fmt.pix.bytesperline * fmt.fmt.pix.height);
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Start capturing
    ret = ioctl(fd, VIDIOC_STREAMON, &buf_info.type);
    if (ret) {
        fprintf(stderr, "Failed to start capturing: %d\n", ret);
        munmap(buf, req.count * fmt.fmt.pix.bytesperline * fmt.fmt.pix.height);
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Capture frames
    for (int i = 0; i < FRAMES; i++) {
        // Trigger the capture
        gpiod_line_set_value(line, 1);

        // Wait for the capture to complete
        usleep(50000);

        // Get the buffer info
        ret = ioctl(fd, VIDIOC_DQBUF, &buf_info);
        if (ret) {
            fprintf(stderr, "Failed to get buffer info: %d\n", ret);
            break;
        }

        // Save the image
        FILE *fp = fopen("image.jpg", "wb");
        if (!fp) {
            fprintf(stderr, "Failed to open file\n");
            break;
        }
        fwrite(buf, 1, buf_info.bytesused, fp);
        fclose(fp);

        // Queue the buffer
        ret = ioctl(fd, VIDIOC_QBUF, &buf_info);
        if (ret) {
            fprintf(stderr, "Failed to queue buffer: %d\n", ret);
            break;
        }
    }

    // Stop capturing
    ret = ioctl(fd, VIDIOC_STREAMOFF, &buf_info.type);
    if (ret) {
        fprintf(stderr, "Failed to stop capturing: %d\n");
    }

    // Unmap the buffer
    munmap(buf, req.count * fmt.fmt.pix.bytesperline * fmt.fmt.pix.height);

    // Release the buffers
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret) {
        fprintf(stderr, "Failed to release buffers: %d\n", ret);
    }

    // Close the device
    close(fd);

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

