#define GPIO_LINE_VALUE 1

int main() {
    int ret;
    struct gpiod_line *line;
    struct gpiod_line_direction *direction;
    struct gpiod_line_value *value;

    // Open the GPIO chip
    line = gpiod_chip_get_line(GPIO_CHIP_NAME, GPIO_LINE_NUMBER);
    if (!line) {
        fprintf(stderr, "Failed to get line %d on chip %s: %s\n", GPIO_LINE_NUMBER, GPIO_CHIP_NAME, gpiod_error());
        return 1;
    }

    // Check if the line is a valid GPIO line
    if (gpiod_line_is_valid(line) != 0) {
        fprintf(stderr, "Line %d is not a valid GPIO line\n", GPIO_LINE_NUMBER);
        gpiod_line_release(line);
        return 1;
    }

    // Get the direction of the line
    direction = gpiod_line_request_output(line, GPIO_LINE_DIRECTION);
    if (!direction) {
        fprintf(stderr, "Failed to request direction for line %d: %s\n", GPIO_LINE_NUMBER, gpiod_error());
        gpiod_line_release(line);
        return 1;
    }

    // Set the initial value of the line
    value = gpiod_line_request_value(line, GPIO_LINE_VALUE);
    if (!value) {
        fprintf(stderr, "Failed to request value for line %d: %s\n", GPIO_LINE_NUMBER, gpiod_error());
        gpiod_line_release(line);
        return 1;
    }

    // Set the initial value of the line
    ret = gpiod_line_set_value(line, GPIO_LINE_VALUE);
    if (ret != 0) {
        fprintf(stderr, "Failed to set value for line %d: %s\n", GPIO_LINE_NUMBER, gpiod_error());
        gpiod_line_release(line);
        return 1;
    }

    // Print the initial value
    printf("Initial value of line %d: %d\n", GPIO_LINE_NUMBER, GPIO_LINE_VALUE);

    // Repeat indefinitely
    while (1) {
        // Set the value of the line
        ret = gpiod_line_set_value(line, GPIO_LINE_VALUE);
        if (ret != 0) {
            fprintf(stderr, "Failed to set value for line %d: %s\n", GPIO_LINE_NUMBER, gpiod_error());
            break;
        }

        // Print the value
        printf("Value of line %d: %d\n", GPIO_LINE_NUMBER, GPIO_LINE_VALUE);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Release the line
    gpiod_line_release(line);

    return 0;
}

