#include <paho_mqtt_client.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_readings"
#define SENSOR_FILE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x12
#define READ_TIMEOUT 1000 // 1 second

// Structure to hold sensor data
typedef struct {
    int32_t temperature;
    int32_t humidity;
} sensor_data_t;

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int fd = open(SENSOR_FILE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open sensor file");
        return -1;
    }

    // Set up I2C bus
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    // Read temperature and humidity
    uint8_t reg[2];
    if (i2c_smbus_read_byte_data(fd, 0x00, reg) < 0) {
        perror("Failed to read temperature");
        close(fd);
        return -1;
    }
    data->temperature = (int32_t)reg[0] << 8 | reg[1];

    if (i2c_smbus_read_byte_data(fd, 0x01, reg) < 0) {
        perror("Failed to read humidity");
        close(fd);
        return -1;
    }
    data->humidity = (int32_t)reg[0] << 8 | reg[1];

    close(fd);
    return 0;
}

// Function to publish sensor data to MQTT
void publish_sensor_data(sensor_data_t *data) {
    char buffer[1024];
    sprintf(buffer, "{\"temperature\": %d, \"humidity\": %d}", data->temperature, data->humidity);
    char *topic = MQTT_TOPIC;
    char *message = buffer;

    // Create MQTT client
    struct paho_mqtt_client *client = paho_mqtt_client_create(NULL, NULL, NULL, NULL);
    if (!client) {
        perror("Failed to create MQTT client");
        return;
    }

    // Connect to MQTT broker
    struct paho_mqtt_client_options *options = paho_mqtt_client_options_new(NULL);
    if (!options) {
        paho_mqtt_client_destroy(client);
        return;
    }
    if (paho_mqtt_client_connect(client, MQTT_BROKER, MQTT_PORT, options, NULL, NULL, NULL, NULL) != 0) {
        paho_mqtt_client_options_destroy(options);
        paho_mqtt_client_destroy(client);
        return;
    }

    // Publish sensor data
    if (paho_mqtt_client_publish(client, topic, strlen(message), message, 1, 0, NULL, NULL) != 0) {
        paho_mqtt_client_disconnect(client, NULL, NULL);
        paho_mqtt_client_destroy(client);
        paho_mqtt_client_options_destroy(options);
        return;
    }

    // Clean up
    paho_mqtt_client_disconnect(client, NULL, NULL);
    paho_mqtt_client_destroy(client);
    paho_mqtt_client_options_destroy(options);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    // Create sensor data structure
    sensor_data_t data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(&data) < 0) {
            // If read fails, skip this iteration
            continue;
        }

        // Publish sensor data
        publish_sensor_data(&data);

        // Wait for 0.01 seconds
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 10000;
        select(0, NULL, NULL, NULL, &tv);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

