    int fd;
    struct termios oldtio, newtio;
    char buffer[256];

    // Open the serial port
    fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Failed to open serial port");
        exit(1);
    }

    // Save the current serial port settings
    if (tcgetattr(fd, &oldtio) < 0) {
        perror("Failed to get serial port settings");
        close(fd);
        exit(1);
    }

    // Set the new serial port settings
    newtio.c_cflag = B9600 | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNBRK | IGNPAR | ICRNL | INLCR;
    newtio.c_oflag = 0;
    newtio.c_lflag = 0;
    newtio.c_cc[VMIN] = 1;
    newtio.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &newtio) < 0) {
        perror("Failed to set serial port settings");
        close(fd);
        exit(1);
    }

    // Read from the serial port
    while (1) {
        if (read(fd, buffer, 256) < 0) {
            perror("Failed to read from serial port");
            break;
        }
        buffer[read(fd, NULL, 0)] = '\0'; // Null-terminate the string
        printf("%s\n", buffer);
        if (strcmp(buffer, "exit") == 0) {
            break;
        }
    }

    // Restore the original serial port settings
    if (tcsetattr(fd, TCSANOW, &oldtio) < 0) {
        perror("Failed to restore serial port settings");
    }

    // Close the serial port
    close(fd);

    return 0;
}

