        uint8_t pressure_msb, pressure_lsb, pressure_xlsb, temperature_msb, temperature_lsb, temperature_xlsb;
        i2c_write(fd, BMP280_ADDRESS, BMP280_REGISTER_PRESSURE);
        i2c_read(fd, BMP280_ADDRESS, &pressure_msb);
        i2c_read(fd, BMP280_ADDRESS, &pressure_lsb);
        i2c_read(fd, BMP280_ADDRESS, &pressure_xlsb);
