    }

    // Get the device capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        fprintf(stderr, "Failed to get device capabilities\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Check if the device is a video device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video device\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Set the format
