    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_BGR24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        fprintf(stderr, "Failed to set format\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Request a buffer
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request buffer\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Map the buffer
    buf = mmap(NULL, FRAMESIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buf == MAP_FAILED) {
        fprintf(stderr, "Failed to map buffer\n");
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Start capturing
    ret = ioctl(fd, VIDIOC_STREAMON, &req.type);
    if (ret < 0) {
        fprintf(stderr, "Failed to start capturing\n");
        munmap(buf, FRAMESIZE);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Capture frames
    while (1) {
