#define SERIAL_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define DATA_BITS 8
#define STOP_BITS 1
#define PARITY 'N'
#define TIMEOUT 0

int main() {
    int fd = -1;
    struct termios oldtio, newtio;

    // Open the serial device
    fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Failed to open serial device");
        goto cleanup;
    }

    // Save the current termios settings
    if (tcgetattr(fd, &oldtio) < 0) {
        perror("Failed to get current termios settings");
        goto cleanup;
    }

    // Set the new termios settings
    newtio = oldtio;
    newtio.c_cflag = (BAUD_RATE | CS8 | CLOCAL | CREAD);
    newtio.c_iflag = IGNBRK | IGNPAR;
    newtio.c_oflag = 0;
    newtio.c_lflag = 0;
    newtio.c_cc[VMIN] = 1;
    newtio.c_cc[VTIME] = TIMEOUT;

    if (cfsetispeed(&newtio, BAUD_RATE) < 0 || cfsetospeed(&newtio, BAUD_RATE) < 0) {
        perror("Failed to set baud rate");
        goto cleanup;
    }

    if (tcsetattr(fd, TCSANOW, &newtio) < 0) {
        perror("Failed to set termios settings");
        goto cleanup;
    }

    // Read from the serial device
    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, 256);
    if (bytes_read < 0) {
        perror("Failed to read from serial device");
        goto cleanup;
    }

    // Print the received data
    printf("Received: %s\n", buffer);

cleanup:
    // Restore the original termios settings
    if (fd >= 0) {
        if (tcsetattr(fd, TCSANOW, &oldtio) < 0) {
            perror("Failed to restore termios settings");
        }
        close(fd);
    }

    return 0;
}

