    struct gpiod_line_event event;
    struct gpiod_line_event_data data;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO line
    line = gpiod_cdev_open(GPIO_LINE, 0);
    if (!line) {
        fprintf(stderr, "Failed to open GPIO line '%s': %d\n", GPIO_LINE_NAME, ret);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Export the GPIO line
    ret = gpiod_line_export(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to export GPIO line '%s': %d\n", GPIO_LINE_NAME, ret);
        gpiod_line_release(line);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the direction of the GPIO line to output
    ret = gpiod_line_request_output(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line '%s' as output: %d\n", GPIO_LINE_NAME, ret);
        gpiod_line_release(line);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state of the GPIO line to 1 (high)
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line '%s' to high: %d\n", GPIO_LINE_NAME, ret);
        gpiod_line_release(line);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Register a signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        // Print the current state of the GPIO line
        ret = gpiod_line_get_value(line, &data);
        if (ret < 0) {
            fprintf(stderr, "Failed to get GPIO line '%s' value: %d\n", GPIO_LINE_NAME, ret);
            break;
        }
        printf("GPIO %s is %s\n", GPIO_LINE_NAME, data.value == 1 ? "high" : "low");

        // Toggle the state of the GPIO line
        ret = gpiod_line_set_value(line, !data.value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line '%s' value: %d\n", GPIO_LINE_NAME, ret);
            break;
        }

        // Sleep for 2 seconds
        usleep(2000000);
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Unregister the signal handler
    sa.sa_handler = SIG_DFL;
    sigaction(SIGINT, &sa, NULL);

    // Exit cleanly
    gpiod_exit();
    return EXIT_SUCCESS;
}

