#include <paho-mqtt-c/client.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x00
#define CHIP_SELECT 17
#define CLOCK 23
#define DATA 24
#define NUM_CHANNELS 8

#define MQTT_SERVER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor"

int i2c_fd;
int gpio_fd;
int gpio_chip_select;
int gpio_clock;
int gpio_data;

struct i2c_client *client;
struct i2c_client_callback callback;
struct i2c_client_callback_data callback_data;

void i2c_read_callback(int client, int event, void *data) {
    if (event == I2C_CLIENT_EVENT_READ) {
        struct i2c_msg msg;
        struct i2c_msg *msgs = (struct i2c_msg *)data;
        int len = msgs->len;
        int ret = i2c_smbus_read_i2c_msg(i2c_fd, msgs);
        if (ret < 0) {
            fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
            exit(1);
        }
        for (int i = 0; i < len; i++) {
            uint8_t val = msgs->msg[i].buf[0];
            // MCP3008 is a 10-bit ADC, so we need to shift the value to the left by 2 bits
            // and then mask the top 6 bits to get the actual value
            uint16_t reading = (val & 0x03) << 8;
            char buffer[20];
            sprintf(buffer, "{\"channel\": %d, \"value\": %d}", i, reading);
            char *topic = MQTT_TOPIC;
            char *payload = buffer;
            int qos = 0;
            int retain = 0;
            int rc = mqtt_publish(client, topic, strlen(topic), payload, strlen(payload), qos, retain);
            if (rc != MQTT_SUCCESS) {
                fprintf(stderr, "Error publishing to MQTT: %s\n", mqtt_strerror(rc));
                exit(1);
            }
        }
    }
}

int main() {
    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpio_strerror(gpio_error()));
        exit(1);
    }
    gpio_clock = gpioOpen(CLOCK, 1);
    if (gpio_clock < 0) {
        fprintf(stderr, "Error opening GPIO pin %d: %s\n", CLOCK, gpio_strerror(gpio_error()));
        exit(1);
    }
    gpio_data = gpioOpen(DATA, 1);
    if (gpio_data < 0) {
        fprintf(stderr, "Error opening GPIO pin %d: %s\n", DATA, gpio_strerror(gpio_error()));
        exit(1);
    }
    gpio_chip_select = gpioOpen(CHIP_SELECT, 1);
    if (gpio_chip_select < 0) {
        fprintf(stderr, "Error opening GPIO pin %d: %s\n", CHIP_SELECT, gpio_strerror(gpio_error()));
        exit(1);
    }
    gpioWrite(gpio_chip_select, 1);
    gpioWrite(gpio_clock, 1);
    gpioWrite(gpio_data, 1);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C address: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize MQTT
    client = mqtt_client_create(NULL);
    if (client == NULL) {
        fprintf(stderr, "Error creating MQTT client\n");
        exit(1);
    }
    mqtt_client_set_options(client, MQTT_CLIENT_DEFAULT);
    mqtt_client_set_clean_session(client, 1);
    mqtt_client_set_keep_alive(client, 60);
    mqtt_client_set_last_will(client, MQTT_TOPIC, strlen(MQTT_TOPIC), "offline", 0);
    mqtt_client_connect(client, MQTT_SERVER, MQTT_PORT, 60, NULL, NULL, NULL);

    // Set up I2C read callback
    callback_data = NULL;
    callback.read = i2c_read_callback;
    callback.write = NULL;
    callback.close = NULL;
    callback_data = malloc(sizeof(struct i2c_client_callback_data));
    if (callback_data == NULL) {
        fprintf(stderr, "Error allocating memory for I2C callback data\n");
        exit(1);
    }
    i2c_client_set_callback(i2c_fd, &callback, callback_data);

    // Start I2C read
    struct i2c_msg msg;
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = malloc(msg.len);
    if (msg.buf == NULL) {
        fprintf(stderr, "Error allocating memory for I2C message\n");
        exit(1);
    }
    msg.buf[0] = 0x00; // Start conversion
    if (i2c_smbus_write_i2c_msg(i2c_fd, &msg) < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        exit(1);
    }

    // Wait for I2C read to complete
    while (1) {
        sleep(1);
    }

    // Clean up
    free(msg.buf);
    i2c_client_set_callback(i2c_fd, NULL, NULL);
    i2c_smbus_close(i2c_fd);
    close(gpio_fd);
    gpioTerminate();
    mqtt_client_disconnect(client);
    mqtt_client_destroy(client);
    free(callback_data);
    return 0;
}

