int main() {
    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_streamparm parm;
    struct v4l2_capability cap;
    char *dev_name = "/dev/video0";

    // Open the device
    fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    // Get device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to get device capabilities");
        close(fd);
        return 1;
    }

    // Check if device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return 1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    // Set streaming parameters
    memset(&parm, 0, sizeof(parm));
    parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    parm.streamparm.capture.timeperframe.numerator = 1;
    parm.streamparm.capture.timeperframe.denominator = 30;
    if (ioctl(fd, VIDIOC_S_PARM, &parm) < 0) {
        perror("Failed to set streaming parameters");
        close(fd);
        return 1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        close(fd);
        return 1;
    }

    // Capture a frame
    char *buf = malloc(WIDTH * HEIGHT * 3);
    if (!buf) {
        perror("Failed to allocate buffer");
        close(fd);
        return 1;
    }
    struct v4l2_buffer buf_struct;
    memset(&buf_struct, 0, sizeof(buf_struct));
    buf_struct.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_struct.memory = V4L2_MEMORY_USERPTR;
    buf_struct.length = WIDTH * HEIGHT * 3;
    buf_struct.m.userptr = (unsigned long)buf;
    if (ioctl(fd, VIDIOC_QBUF, &buf_struct) < 0) {
        perror("Failed to queue buffer");
        free(buf);
        close(fd);
        return 1;
    }
    if (ioctl(fd, VIDIOC_DQBUF, &buf_struct) < 0) {
        perror("Failed to dequeue buffer");
        free(buf);
        close(fd);
        return 1;
    }

    // Save the captured image to a file
    FILE *fp = fopen(FILENAME, "wb");
    if (!fp) {
        perror("Failed to open file");
        free(buf);
        close(fd);
        return 1;
    }
    fwrite(buf, 1, buf_struct.length, fp);
    fclose(fp);
    free(buf);

    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ioctl(fd, VIDIOC_STREAMOFF, &type);

    // Release resources
    close(fd);
    return 0;
}

