    for (int i = GPIO_4; i <= GPIO_9; i++) {
        if (gpioSetPWRRange(i, 1000) < 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d\n", i);
            gpioTerminate();
            return 1;
        }
    }

    // Set PWM duty cycle to 50% for each GPIO
