#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x20
#define DISPLAY_WIDTH 16
#define DISPLAY_HEIGHT 2

// Function to write a byte to the PCF8574
void write_byte(uint8_t value) {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set i2c slave address");
        close(fd);
        exit(1);
    }

    if (write(fd, &value, 1) != 1) {
        perror("Failed to write to i2c bus");
        close(fd);
        exit(1);
    }

    close(fd);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize gpio\n");
        return 1;
    }

    // Initialize the PCF8574
    write_byte(0x00); // Reset the display

    int i = 0;
    while (1) {
        // Clear the display
        write_byte(0x00);

        // Write the current value to the display
        for (int j = 0; j < DISPLAY_WIDTH; j++) {
            uint8_t value = (i % 10) + '0';
            write_byte(0x80 | j);
            write_byte(value);
        }

        // Move to the next line
        write_byte(0xC0);

        // Write the current value to the display
        for (int j = 0; j < DISPLAY_WIDTH; j++) {
            uint8_t value = (i / 10) % 10 + '0';
            write_byte(0x80 | j);
            write_byte(value);
        }

        // Increment the value
        i++;

        // Wait 0.5 seconds
        usleep(500000);

        // Check for interrupt
        if (gpioWaitForEvent(GPIO_NONE, GPIO_EVENT_RISING_EDGE) == -1) {
            fprintf(stderr, "Error waiting for event\n");
            gpioTerminate();
            return 1;
        }
    }

    // Clean up
    gpioTerminate();
    return 0;
}

