#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define WIDTH 640
#define HEIGHT 480
#define FRAMES 10

static int v4l2_fd = -1;
static volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_streamparm parm;
    struct v4l2_format fmt_out;
    uint8_t *buf;
    int i;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the video device
    v4l2_fd = open("/dev/video0", O_RDWR);
    if (v4l2_fd < 0) {
        perror("Failed to open video device");
        return 1;
    }

    // Check if the device is a video device
    if (ioctl(v4l2_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query video device capabilities");
        close(v4l2_fd);
        return 1;
    }

    // Check if the device is a video device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video device\n");
        close(v4l2_fd);
        return 1;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;
    if (ioctl(v4l2_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        close(v4l2_fd);
        return 1;
    }

    // Request a buffer
    memset(&parm, 0, sizeof(parm));
    parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    parm.streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    parm.streamparm.strength = 0;
    parm.streamparm.timeperframe.numerator = 1;
    parm.streamparm.timeperframe.denominator = 100;
    if (ioctl(v4l2_fd, VIDIOC_S_PARM, &parm) < 0) {
        perror("Failed to set video parameters");
        close(v4l2_fd);
        return 1;
    }

    // Request a buffer
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_USERPTR;
    req.count = 1;
    req.length = sizeof(uint8_t) * WIDTH * HEIGHT;
    if (ioctl(v4l2_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffer");
        close(v4l2_fd);
        return 1;
    }

    // Map the buffer
    buf = malloc(req.count * req.length);
    if (!buf) {
        perror("Failed to allocate buffer");
        close(v4l2_fd);
        return 1;
    }

    // Start capturing
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(v4l2_fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start capturing");
        free(buf);
        close(v4l2_fd);
        return 1;
    }

    // Capture frames
    for (i = 0; running && i < FRAMES; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_USERPTR;
        buf.index = 0;
        buf.m.userptr = (uint64_t)buf;
        buf.length = req.length;
        if (ioctl(v4l2_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            break;
        }
        if (read(v4l2_fd, buf, req.length) < 0) {
            perror("Failed to read from device");
            break;
        }
        printf("Captured frame %d\n", i);
        // Save the captured image to a file
        FILE *f = fopen("image.raw", "wb");
        if (!f) {
            perror("Failed to open file for writing");
            break;
        }
        fwrite(buf, 1, req.length, f);
        fclose(f);
        usleep(100000);
    }

    // Stop capturing
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(v4l2_fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop capturing");
    }

    // Unmap the buffer
    free(buf);

    // Release the buffer
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_USERPTR;
    req.count = 0;
    if (ioctl(v4l2_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to release buffer");
    }

    // Close the device
    close(v4l2_fd);

    return 0;
}

