    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write to display
    uint8_t data = 0x00;
    for (int i = 0; i < 8; i++) {
