    if (ret < 0) {
        fprintf(stderr, "Failed to get line: %s\n", gpiod_error_str(ret));
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Export the line
    ret = gpiod_line_export(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to export line: %s\n", gpiod_error_str(ret));
        gpiod_line_release(line);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Set the direction of the line to output
    ret = gpiod_line_request_output(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set direction: %s\n", gpiod_error_str(ret));
        gpiod_line_release(line);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Set the initial state of the line to 0
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set initial value: %s\n", gpiod_error_str(ret));
        gpiod_line_release(line);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Set up a consumer to report changes to the line
    ret = gpiod_line_event_subscribe(line, &event, &consumers);
    if (ret < 0) {
        fprintf(stderr, "Failed to subscribe to events: %s\n", gpiod_error_str(ret));
        gpiod_line_release(line);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle the line
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret < 0) {
            fprintf(stderr, "Failed to set value: %s\n", gpiod_error_str(ret));
            break;
        }

        // Print the current state
        printf("%d\n", gpiod_line_get_value(line));

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Unsubscribe from events
    gpiod_line_event_unsubscribe(&consumers);

    // Release the line
    gpiod_line_release(line);

    // Close the chip
    gpiod_chip_close(ret);

    return EXIT_SUCCESS;
}

