    usleep(10);
    uint16_t raw = i2c_read_word(fd);
    if (raw & 0x0003) {
        printf("Invalid temperature reading\n");
        return;
    }
    float temperature = (raw / 65536.0) * 175.72 - 46.85;
    printf("Temperature: %.2f°C\n", temperature);
}

