    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Open the GPIO line
    line = gpiod_cdev_open(GPIO_LINE, GPIOD_LINE_DIRECTION_OUTPUT);
    if (!line) {
        fprintf(stderr, "Failed to open GPIO line '%s': %d\n", GPIO_LINE, ret);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set the initial state of the GPIO line to 1 (high)
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set initial state of GPIO line '%s': %d\n", GPIO_LINE, ret);
        gpiod_line_release(line);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set up a line event to detect state changes
    ret = gpiod_line_request_event(line, GPIOD_LINE_EVENT_STATE_CHANGED, GPIOD_LINE_EVENT_DATA_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request event on GPIO line '%s': %d\n", GPIO_LINE, ret);
        gpiod_line_release(line);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Get the current state of the GPIO line
        ret = gpiod_line_get_value(line, &data);
        if (ret < 0) {
            fprintf(stderr, "Failed to get value of GPIO line '%s': %d\n", GPIO_LINE, ret);
            break;
