            break;
        }

        // Sleep for 0.05 seconds
        usleep(50000);
    }

    // Release the line event
    gpiod_line_release_event(line);

    // Release the GPIO line
    gpiod_line_release(line);

    // Release libgpiod
    gpiod_exit();

    return EXIT_SUCCESS;
}

