#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define FREQUENCY 1000  // Hz
#define DUTY_CYCLE_MIN 0
#define DUTY_CYCLE_MAX 100
#define DUTY_CYCLE_INCREMENT 10

int main() {
    int duty_cycle = DUTY_CYCLE_MIN;
    int gpio_4 = 0;
    int gpio_17 = 0;
    int gpio_18 = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up PWM on GPIO 4, 17, and 18
    if (gpioSetMode(GPIO_4, PI_OUTPUT_PWM) < 0) {
        fprintf(stderr, "Failed to set GPIO 4 as PWM output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_17, PI_OUTPUT_PWM) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as PWM output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_18, PI_OUTPUT_PWM) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as PWM output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set the PWM frequency
    if (gpioSetPWMfrequency(GPIO_4, FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO 4\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_17, FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO 17\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_18, FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set the initial duty cycle
    if (gpioPWM(GPIO_4, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set duty cycle on GPIO 4\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(GPIO_17, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set duty cycle on GPIO 17\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(GPIO_18, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set duty cycle on GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Print the current duty cycle
        printf("Duty cycle: %d%%\n", duty_cycle);

        // Update the duty cycle
        duty_cycle = (duty_cycle + DUTY_CYCLE_INCREMENT) % (DUTY_CYCLE_MAX + 1);

        // Set the new duty cycle
        if (gpioPWM(GPIO_4, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set duty cycle on GPIO 4\n");
            break;
        }
        if (gpioPWM(GPIO_17, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set duty cycle on GPIO 17\n");
            break;
        }
        if (gpioPWM(GPIO_18, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set duty cycle on GPIO 18\n");
            break;
        }

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Release the hardware
    gpioTerminate();

    return EXIT_SUCCESS;
}

