#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25

int main() {
    int status;
    int value = 0;

    // Initialize pigpio
    if ((status = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", status);
        return 1;
    }

    // Set up PWM on GPIO 17, 18, 22, 23, 24, 25
    for (int i = GPIO_17; i <= GPIO_25; i++) {
        if ((status = gpioSetMode(i, PI_PWM)) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d: %d\n", i, status);
            gpioTerminate();
            return 1;
        }
    }

    // Set PWM frequency to 1000 Hz
    for (int i = GPIO_17; i <= GPIO_25; i++) {
        if ((status = gpioSetPWMfrequency(i, 1000)) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d: %d\n", i, status);
            gpioTerminate();
            return 1;
        }
    }

    while (1) {
        // Set PWM duty cycle to 0-100%
        for (int i = GPIO_17; i <= GPIO_25; i++) {
            if ((status = gpioPWM(i, value)) < 0) {
                fprintf(stderr, "Failed to set PWM for GPIO %d: %d\n", i, status);
                gpioTerminate();
                return 1;
            }
            printf("GPIO %d: %d%%\n", i, value);
        }

        // Increment duty cycle
        value = (value + 1) % 101;

        // Sleep for 50ms
        if ((status = gpioDelay(50000)) < 0) {
            fprintf(stderr, "Failed to delay: %d\n", status);
            gpioTerminate();
            return 1;
        }
    }

    // Clean up
    for (int i = GPIO_17; i <= GPIO_25; i++) {
        if ((status = gpioPWM(i, 0)) < 0) {
            fprintf(stderr, "Failed to clear PWM for GPIO %d: %d\n", i, status);
        }
    }

    gpioTerminate();
    return 0;
}

