#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 27
#define GPIO_LINE "gpiochip0"
#define GPIO_LINE_NAME "gpio27"

int main() {
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;

    // Initialize libgpiod
    if ((ret = gpiod_init()) < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %d\n", ret);
        return 1;
    }

    // Open the GPIO line
    if ((line = gpiod_line_request_output(GPIO_LINE_NAME, GPIOD_LINE_REQUEST_LINE, GPIOD_LINE_REQUEST_ACTIVE_LOW)) == NULL) {
        fprintf(stderr, "Failed to open GPIO line: %d\n", ret);
        gpiod_exit();
        return 1;
    }

    // Set the initial state to 0 (low)
    if ((ret = gpiod_line_set_value(line, 0)) < 0) {
        fprintf(stderr, "Failed to set initial state: %d\n", ret);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }

    // Set up a line event to detect state changes
    if ((ret = gpiod_line_event_subscribe(line, GPIOD_LINE_EVENT_STATE_CHANGED, &event, NULL)) < 0) {
        fprintf(stderr, "Failed to subscribe to line events: %d\n", ret);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle the state
        if ((ret = gpiod_line_set_value(line, !gpiod_line_get_value(line))) < 0) {
            fprintf(stderr, "Failed to set state: %d\n", ret);
            break;
        }

        // Print the current state
        printf("%s\n", gpiod_line_get_value(line) ? "High" : "Low");

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Unsubscribe from line events
    gpiod_line_event_unsubscribe(&event);

    // Release the GPIO line
    gpiod_line_release(line);

    // Release libgpiod resources
    gpiod_exit();

    return 0;
}

