#define BMP280_ADDRESS 0x03
#define BMP280_REGISTER_PRESSURE 0xF4
#define BMP280_REGISTER_PRESSURE_MSB 0xF6
#define BMP280_REGISTER_PRESSURE_LSB 0xF7
#define BMP280_REGISTER_PRESSURE_XLSB 0xF8
#define BMP280_REGISTER_TEMPERATURE 0xFA
#define BMP280_REGISTER_TEMPERATURE_MSB 0xFB
#define BMP280_REGISTER_TEMPERATURE_LSB 0xFC
#define BMP280_REGISTER_TEMPERATURE_XLSB 0xFD

int i2c_open(const char *filename) {
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }
    return fd;
}

int i2c_write(int fd, uint8_t address, uint8_t value) {
    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .buf = &value,
        .len = 1
    };
    struct i2c_msg msgs[] = {msg};
    int ret = ioctl(fd, I2C_SLAVE, address);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    ret = i2c_transfer(fd, msgs, 1);
    if (ret < 0) {
        perror("Failed to write to I2C device");
        exit(1);
    }
    return ret;
}

int i2c_read(int fd, uint8_t address, uint8_t *value) {
    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .buf = value,
        .len = 1
    };
    struct i2c_msg msgs[] = {msg};
    int ret = i2c_transfer(fd, msgs, 1);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        exit(1);
    }
    return ret;
}

int main() {
    const char *filename = "/dev/i2c-1";
    int fd = i2c_open(filename);
    if (fd < 0) {
        return 1;
    }

    // Set up BMP280 to read pressure and temperature
    i2c_write(fd, BMP280_ADDRESS, 0xF2 & ~(1 << 6)); // Pressure and temperature
    i2c_write(fd, BMP280_ADDRESS, 0xF4 & ~(1 << 6)); // Pressure and temperature

    for (int i = 0; i < 3; i++) {
        // Read temperature
        i2c_write(fd, BMP280_ADDRESS, BMP280_REGISTER_TEMPERATURE);
        uint8_t temp_msb, temp_lsb, temp_xlsb;
        i2c_read(fd, BMP280_ADDRESS, &temp_msb);
        i2c_read(fd, BMP280_ADDRESS, &temp_lsb);
        i2c_read(fd, BMP280_ADDRESS, &temp_xlsb);
        uint16_t temp = (temp_msb << 8) | temp_lsb;
        temp = (temp << 8) | temp_xlsb;
        float temperature = (temp / 100.0f) * 165.0f + 25.0f;
        printf("Temperature: %.2f°C\n", temperature);

        // Read pressure
        i2c_write(fd, BMP280_ADDRESS, BMP280_REGISTER_PRESSURE);
        uint8_t pres_msb, pres_lsb, pres_xlsb;
        i2c_read(fd, BMP280_ADDRESS, &pres_msb);
        i2c_read(fd, BMP280_ADDRESS, &pres_lsb);
        i2c_read(fd, BMP280_ADDRESS, &pres_xlsb);
        uint32_t pres = (pres_msb << 16) | pres_lsb;
        pres = (pres << 8) | pres_xlsb;
        float pressure = (pres / 262144.0f) * 100.0f;
        printf("Pressure: %.2f hPa\n", pressure);

        sleep(1);
    }

    close(fd);
    return 0;
}

