#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_SLAVE 0x0703
#define BME280_I2C_ADDRESS 0x76
#define BME280_REGISTER_PRESSURE 0xF7
#define BME280_REGISTER_TEMP 0xF3
#define BME280_REGISTER_HUMIDITY 0xFD

int i2c_open(const char *filename) {
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }
    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(1);
    }
    return fd;
}

void i2c_close(int fd) {
    close(fd);
}

void read_bme280(int fd) {
    uint8_t data[3];
    if (i2c_smbus_write_byte(fd, BME280_REGISTER_PRESSURE) < 0) {
        perror("Failed to write to BME280 pressure register");
        i2c_close(fd);
        exit(1);
    }
    if (i2c_smbus_read_i2c_block_data(fd, BME280_REGISTER_PRESSURE, 3, data) < 0) {
        perror("Failed to read from BME280 pressure register");
        i2c_close(fd);
        exit(1);
    }
    uint32_t pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    printf("Pressure: %d Pa\n", pressure);

    if (i2c_smbus_write_byte(fd, BME280_REGISTER_TEMP) < 0) {
        perror("Failed to write to BME280 temperature register");
        i2c_close(fd);
        exit(1);
    }
    if (i2c_smbus_read_i2c_block_data(fd, BME280_REGISTER_TEMP, 2, data) < 0) {
        perror("Failed to read from BME280 temperature register");
        i2c_close(fd);
        exit(1);
    }
    int16_t temp = (data[0] << 8) | data[1];
    printf("Temperature: %d C\n", temp / 100);

    if (i2c_smbus_write_byte(fd, BME280_REGISTER_HUMIDITY) < 0) {
        perror("Failed to write to BME280 humidity register");
        i2c_close(fd);
        exit(1);
    }
    if (i2c_smbus_read_i2c_block_data(fd, BME280_REGISTER_HUMIDITY, 2, data) < 0) {
        perror("Failed to read from BME280 humidity register");
        i2c_close(fd);
        exit(1);
    }
    uint16_t humidity = (data[0] << 8) | data[1];
    printf("Humidity: %d %%\n", humidity);
}

int main() {
    const char *filename = "/dev/i2c-1";
    int fd = i2c_open(filename);
    for (int i = 0; i < 3; i++) {
        read_bme280(fd);
        sleep(5);
    }
    i2c_close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
