#define GPIO_CHIP_NAME "/dev/gpiochip0"
#define GPIO_LINE_NUMBER 17

int main() {
    int ret;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    struct gpiod_line_event_data data;
    struct gpiod_line_event_data *event_data;
    struct gpiod_chip *chip;

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Get the line
    line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER);
    if (!line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE_NUMBER);
        gpiod_chip_close(chip);
        return 1;
    }

    // Export the line
    ret = gpiod_line_export(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to export line %d: %d\n", GPIO_LINE_NUMBER, ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the direction to output
    ret = gpiod_line_request_output(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to set direction of line %d: %d\n", GPIO_LINE_NUMBER, ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the initial state to 1 (high)
    ret = gpiod_line_set_value(line, 1);
    if (ret) {
        fprintf(stderr, "Failed to set initial value of line %d: %d\n", GPIO_LINE_NUMBER, ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Register for events
    ret = gpiod_line_event_subscribe(line, GPIOD_LINE_EVENT_VALUE, &event, &event_data, NULL);
    if (ret) {
        fprintf(stderr, "Failed to subscribe to events on line %d: %d\n", GPIO_LINE_NUMBER, ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current value
        ret = gpiod_line_get_value(line, &data);
        if (ret) {
            fprintf(stderr, "Failed to get value of line %d: %d\n", GPIO_LINE_NUMBER, ret);
            break;
        }

        // Print the current value
        printf("Line %d is %s\n", GPIO_LINE_NUMBER, data.value == 1 ? "high" : "low");

        // Toggle the value
        ret = gpiod_line_set_value(line, !data.value);
        if (ret) {
            fprintf(stderr, "Failed to set value of line %d: %d\n", GPIO_LINE_NUMBER, ret);
            break;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Unsubscribe from events
    gpiod_line_event_unsubscribe(&event);

    // Release the line
    gpiod_line_release(line);

    // Close the chip
    gpiod_chip_close(chip);

    return 0;
}

