    int ret;

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    // Set the I2C bus to use the VEML7700 address
    ret = ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        goto cleanup;
    }

    // Enable the VEML7700
    uint8_t control = 0x03; // Enable continuous conversion and 1x gain
    ret = i2c_smbus_write_byte_data(i2c_fd, VEML7700_REG_CONTROL, control);
    if (ret < 0) {
        perror("Failed to write to VEML7700 control register");
        goto cleanup;
