// Function to handle signal to exit cleanly
void sigint_handler(int sig) {
    // Release the serial port
    close(serial_fd);
    exit(0);
}

int main() {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open the serial port
    const char *device = "/dev/ttyAMA0"; // Default serial port for Raspberry Pi
    serial_fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd == -1) {
        perror("open");
        exit(1);
    }

    // Set up the serial port
    struct termios tty;
    if (tcgetattr(serial_fd, &tty) == -1) {
        perror("tcgetattr");
        close(serial_fd);
        exit(1);
    }
    cfsetispeed(&tty, B115200);
    cfsetospeed(&tty, B115200);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;
    if (tcsetattr(serial_fd, TCSANOW, &tty) == -1) {
        perror("tcsetattr");
        close(serial_fd);
        exit(1);
    }

    // Set up the signal handler to release the serial port on exit
    atexit(close);

    // Main loop
    char buffer[256];
    while (1) {
        // Read from the serial port
        int bytes_read = read(serial_fd, buffer, 256);
        if (bytes_read == -1) {
            if (errno == EAGAIN) {
                // If the device does not respond, give up and exit
                perror("read");
                close(serial_fd);
                exit(1);
            } else {
                perror("read");
                close(serial_fd);
                exit(1);
            }
        }
        if (bytes_read == 0) {
            // If the device is absent, report the error and exit
            perror("read");
            close(serial_fd);
            exit(1);
        }
        // Print the received data
        write(STDOUT_FILENO, buffer, bytes_read);
        // Repeat once every 0.1 seconds
        usleep(100000);
    }

    return 0;
}

