#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 8
#define GPIO_LINE "gpiochip0"
#define GPIO_LINE_NAME "gpio8"

int main() {
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;

    // Initialize libgpiod
    if ((ret = gpiod_init()) < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %d\n", ret);
        return 1;
    }

    // Open the GPIO line
    if ((line = gpiod_line_request_output(GPIO_LINE_NAME, GPIOD_LINE_REQUEST_LINE, GPIOD_LINE_REQUEST_ACTIVE_HIGH)) == NULL) {
        fprintf(stderr, "Failed to open GPIO line: %d\n", ret);
        gpiod_exit();
        return 1;
    }

    // Set the initial state to 0 (low)
    if ((ret = gpiod_line_set_value(line, 0)) < 0) {
        fprintf(stderr, "Failed to set initial state: %d\n", ret);
        gpiod_line_release(line);
        gpiod_exit();
        return 1;
    }

    // Print the initial state
    printf("Initial state: 0\n");

    // Main loop
    while (1) {
        // Toggle the state
        if ((ret = gpiod_line_set_value(line, !gpiod_line_get_value(line))) < 0) {
            fprintf(stderr, "Failed to toggle state: %d\n", ret);
            break;
        }

        // Print the new state
        printf("State: %d\n", gpiod_line_get_value(line));

        // Wait for 1ms
        usleep(1000);
    }

    // Release the line
    gpiod_line_release(line);

    // Exit libgpiod
    gpiod_exit();

    return 0;
}

