#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_DATA 0x32
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31

int main() {
    int i2c_fd;
    int ret;
    uint8_t data[6];

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the ADXL345
    uint8_t power_ctl = 0x08; // Enable measurement
    if (write(i2c_fd, &power_ctl, 1) != 1) {
        perror("Failed to write to ADXL345");
        close(i2c_fd);
        return 1;
    }

    // Set the data format to 16-bit
    uint8_t data_format = 0x00; // 16-bit data
    if (write(i2c_fd, &data_format, 1) != 1) {
        perror("Failed to write to ADXL345");
        close(i2c_fd);
        return 1;
    }

    // Read the data
    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read from ADXL345");
        close(i2c_fd);
        return 1;
    }

    // Print the data
    for (int i = 0; i < 6; i++) {
        printf("%d ", data[i]);
    }
    printf("\n");

    // Close the I2C bus
    close(i2c_fd);

    // Release the GPIO resources
    gpioTerminate();

    return 0;
}

