#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ENABLE_INT 0x81
#define TCS34725_ENABLE_INT_EN 0x82
#define TCS34725_ENABLE_INT_DIS 0x83
#define TCS34725_INT_STATUS 0x84
#define TCS34725_INT_STATUS_CLR 0x85
#define TCS34725_ID 0x44
#define TCS34725_R 0x0F
#define TCS34725_G 0x10
#define TCS34725_B 0x11
#define TCS34725_C 0x12
#define TCS34725_ENABLE_INT_EN_VAL 0x01

int i2c_open(const char *filename) {
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }
    return fd;
}

int i2c_write(int fd, uint8_t address, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {address, value};
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        exit(1);
    }
    return 0;
}

int i2c_read(int fd, uint8_t address, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(1);
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        exit(1);
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

