    int fd = i2c_open("/dev/i2c-1");
    if (i2c_write(fd, TCS34725_ADDRESS, TCS34725_ENABLE, TCS34725_ENABLE_INT_EN_VAL) < 0) {
        perror("Failed to enable interrupt");
        goto cleanup;
    }

    while (1) {
        uint16_t r, g, b, c;
        if (i2c_read(fd, TCS34725_ADDRESS, TCS34725_R, &r) < 0) {
            perror("Failed to read red channel");
            goto cleanup;
        }
        if (i2c_read(fd, TCS34725_ADDRESS, TCS34725_G, &g) < 0) {
            perror("Failed to read green channel");
            goto cleanup;
        }
        if (i2c_read(fd, TCS34725_ADDRESS, TCS34725_B, &b) < 0) {
            perror("Failed to read blue channel");
            goto cleanup;
        }
        if (i2c_read(fd, TCS34725_ADDRESS, TCS34725_C, &c) < 0) {
            perror("Failed to read clear channel");
            goto cleanup;
        }
        printf("Red: %d, Green: %d, Blue: %d, Clear: %d\n", r, g, b, c);
        usleep(500000);
    }

cleanup:
    close(fd);
    return 0;
}

