// Function to handle signal interrupt
void sigint_handler(int sig) {
    // Release the serial port
    close(serial_fd);
    exit(0);
}

int main() {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open the serial port
    const char *device = "/dev/ttyUSB0"; // Replace with your serial device
    serial_fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd == -1) {
        perror("open");
        exit(1);
    }

    // Set up the serial port
    struct termios tty;
    if (tcgetattr(serial_fd, &tty) == -1) {
        perror("tcgetattr");
        close(serial_fd);
        exit(1);
    }
    cfsetispeed(&tty, B9600); // Set baud rate to 9600
    cfsetospeed(&tty, B9600);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8; // 8 bits
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;
    if (tcsetattr(serial_fd, TCSANOW, &tty) == -1) {
        perror("tcsetattr");
        close(serial_fd);
        exit(1);
    }

    // Main loop
    char buffer[256];
    while (1) {
        // Read from the serial port
        int bytes_read = read(serial_fd, buffer, 256);
        if (bytes_read == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit cleanly
                break;
            } else {
                perror("read");
                close(serial_fd);
                exit(1);
            }
        }
        if (bytes_read == 0) {
            // No data available, wait a bit and try again
            usleep(100000);
            continue;
        }
        // Print the received data
        fwrite(buffer, 1, bytes_read, stdout);
        fflush(stdout);
        // Repeat every 0.1 seconds
        usleep(100000);
    }

    // Release the serial port
    close(serial_fd);
    return 0;
}

