int i2c_open(const char *filename) {
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    return fd;
}

int i2c_write(int fd, uint8_t address, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {address, reg};
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (write(fd, &value, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    return 0;
}

int i2c_read(int fd, uint8_t address, uint8_t reg, uint8_t *value) {
    uint8_t buffer[2] = {address, reg};
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
